USE msdb;
GO

EXEC dbo.sp_add_job
    @job_name    = N'Nightly Index Maintenance',
    @enabled     = 1,
    @description = N'Rebuild or reorganize fragmented indexes.';

EXEC dbo.sp_add_jobstep
    @job_name       = N'Nightly Index Maintenance',
    @step_name      = N'Run index maintenance',
    @subsystem      = N'TSQL',
    @command        = N'EXEC dbo.usp_IndexMaintenance @RebuildThreshold = 30;',
    @retry_attempts = 2,
    @retry_interval = 5;

EXEC dbo.sp_add_schedule
    @schedule_name     = N'Daily at 02:00',
    @freq_type         = 4,
    @freq_interval     = 1,
    @active_start_time = 020000;

EXEC dbo.sp_attach_schedule
    @job_name      = N'Nightly Index Maintenance',
    @schedule_name = N'Daily at 02:00';

EXEC dbo.sp_add_jobserver
    @job_name = N'Nightly Index Maintenance';
GO
